def evaluate_truth(statement, context):
    """
    Evaluates the 'Truth' of a statement based on 'Harm Reduction' (Axiom 3) rather than raw 'Factuality'.

    Args:
        statement (str): The statement being evaluated.
        context (dict): A dictionary containing information about the situation.
                         Expected keys:
                             - 'lie': bool (True if the statement is a lie, False otherwise)
                             - 'family_at_risk': bool (True if the family is at immediate risk, False otherwise)
                             - 'risk_severity': str (Severity of the risk: 'low', 'medium', 'high')
                             - 'potential_harm_from_truth': str (Severity of harm if the truth is revealed: 'low', 'medium', 'high')
                             - 'potential_harm_from_lie': str (Severity of harm if the lie is maintained: 'low', 'medium', 'high')

    Returns:
        str: 'Truth' if the lie is ethically justifiable based on harm reduction, 'Falsehood' otherwise.
    """

    if not isinstance(context, dict):
        return "Invalid context.  Context must be a dictionary."

    required_keys = ['lie', 'family_at_risk', 'risk_severity', 'potential_harm_from_truth', 'potential_harm_from_lie']
    for key in required_keys:
        if key not in context:
            return f"Invalid context. Missing key: {key}"

